class FixedSequenceDiceStrategy implements DiceStrategy {
    private int[] sequence; // the pre-determined rolls to play back
    private int index = 0;  // how many rolls have been produced so far

    FixedSequenceDiceStrategy(int[] sequence) {
        this.sequence = sequence; // store the sequence exactly as given
    }

    @Override
    public int roll() {
        int value = sequence[index % sequence.length]; // wrap around if we run out
        index++; // move to the next roll for next time
        return value; // hand back this roll's result
    }
