import java.util.Map;
import java.util.HashMap;

// Holds the board size and every snake/ladder mapping in one place
class Board {
    private int size;                                // total number of cells, e.g. 30
    private Map<Integer, Integer> snakesAndLadders;   // start cell -> destination cell

    Board(int size, Map<Integer, Integer> snakesAndLadders) {
        this.size = size;                             // remember the board's total length
        this.snakesAndLadders = snakesAndLadders;      // remember every snake and ladder
    }

    int getSize() {
        return size; // simple accessor, no computation needed
    }

    // Given a cell a player just landed on, returns where they ACTUALLY end up:
    // the same cell if nothing is there, or the snake/ladder destination if one is
    int getFinalPosition(int position) {
        return snakesAndLadders.getOrDefault(position, position);
        // getOrDefault returns the mapped value if position is a key,
        // otherwise it returns position itself unchanged
    }
}

// Factory pattern: validates a board's snakes and ladders BEFORE the board
// is ever created, so an invalid configuration can never exist at all
class BoardFactory {
    static Board createBoard(int size, Map<Integer, Integer> snakes, Map<Integer, Integer> ladders) {
        Map<Integer, Integer> combined = new HashMap<>(); // will hold both snakes and ladders together

        for (Map.Entry<Integer, Integer> entry : snakes.entrySet()) {
            // a snake must always move a player DOWN the board (start higher than end)
            if (entry.getKey() <= entry.getValue()) {
                throw new IllegalArgumentException("Snake must move a player DOWN the board");
            }
            combined.put(entry.getKey(), entry.getValue()); // record this snake
        }

        for (Map.Entry<Integer, Integer> entry : ladders.entrySet()) {
            // a ladder must always move a player UP the board (start lower than end)
            if (entry.getKey() >= entry.getValue()) {
                throw new IllegalArgumentException("Ladder must move a player UP the board");
            }
            // a single cell cannot be both a snake start AND a ladder start
            if (combined.containsKey(entry.getKey())) {
                throw new IllegalArgumentException("Cell " + entry.getKey() + " already has a snake or ladder");
            }
            combined.put(entry.getKey(), entry.getValue()); // record this ladder
        }

        return new Board(size, combined); // only reachable if every check above passed
    }
}

