#include <unordered_map>
#include <stdexcept>
using namespace std;

// Holds the board size and every snake/ladder mapping in one place
class Board {
private:
    int size;                                  // total number of cells, e.g. 30
    unordered_map<int, int> snakesAndLadders;   // start cell maps to destination cell

public:
    Board(int size, unordered_map<int, int> snakesAndLadders)
        : size(size), snakesAndLadders(snakesAndLadders) {}

    int getSize() {
        return size; // simple accessor, no computation needed
    }

    int getFinalPosition(int position) {
        auto it = snakesAndLadders.find(position); // look up this cell
        if (it != snakesAndLadders.end()) return it->second; // found: return the destination
        return position; // not found: the player just stays where they landed
    }
};

// Factory pattern: validates a board's snakes and ladders BEFORE the board
// is ever created, so an invalid configuration can never exist at all
class BoardFactory {
public:
    static Board createBoard(int size, unordered_map<int, int> snakes, unordered_map<int, int> ladders) {
        unordered_map<int, int> combined; // will hold both snakes and ladders together

        for (auto& entry : snakes) {
            // a snake must always move a player DOWN the board (start higher than end)
            if (entry.first <= entry.second) {
                throw invalid_argument("Snake must move a player DOWN the board");
            }
            combined[entry.first] = entry.second; // record this snake
        }

        for (auto& entry : ladders) {
            // a ladder must always move a player UP the board (start lower than end)
            if (entry.first >= entry.second) {
                throw invalid_argument("Ladder must move a player UP the board");
            }
            // a single cell cannot be both a snake start AND a ladder start
            if (combined.find(entry.first) != combined.end()) {
                throw invalid_argument("Cell already has a snake or ladder");
            }
            combined[entry.first] = entry.second; // record this ladder
        }

        return Board(size, combined); // only reachable if every check above passed
    }
};

