import java.util.List;
import java.util.ArrayList;

// Orchestrates the whole game: whose turn it is, rolling, moving,
// checking for snakes/ladders, and notifying listeners of every event
public class SnakeAndLadderGame {
    private Board board;                          // the fixed board layout
    private DiceStrategy dice;                     // however dice rolls are produced
    private List<Player> players;                  // every player in turn order
    private int currentPlayerIndex;                // whose turn it is right now
    private List<GameListener> listeners = new ArrayList<>(); // everyone watching for events

    public SnakeAndLadderGame(Board board, DiceStrategy dice, List<Player> players) {
        this.board = board;                        // store the board
        this.dice = dice;                           // store the dice strategy
        this.players = players;                     // store the player list
        this.currentPlayerIndex = 0;                // the first player in the list goes first
    }

    public void addListener(GameListener listener) {
        listeners.add(listener); // register a new observer, does not replace existing ones
    }

    // Plays exactly one turn for whichever player is currently up.
    // Returns true only if that turn caused someone to win.
    public boolean playTurn() {
        Player player = players.get(currentPlayerIndex); // whose turn is it
        int roll = dice.roll();                          // ask the dice strategy for a value
        int newPosition = player.getPosition() + roll;    // where would this roll take them

        if (newPosition > board.getSize()) {
            // overshooting the final cell is not allowed, this turn is simply wasted
            currentPlayerIndex = (currentPlayerIndex + 1) % players.size(); // move to next player
            return false; // nobody won on a wasted turn
        }

        // ask the board whether this landing cell has a snake or ladder on it
        int finalPosition = board.getFinalPosition(newPosition);

        if (finalPosition < newPosition) {
            // landed lower than where the dice roll put them: a snake bit them
            for (GameListener listener : listeners) {
                listener.onSnakeBite(player, newPosition, finalPosition);
            }
        } else if (finalPosition > newPosition) {
            // landed higher than where the dice roll put them: a ladder was climbed
            for (GameListener listener : listeners) {
                listener.onLadderClimb(player, newPosition, finalPosition);
            }
        }
        // if finalPosition equals newPosition, nothing special happened, no event fires

        player.setPosition(finalPosition); // actually update the player's position now

        if (finalPosition == board.getSize()) {
            // reaching the exact final cell means this player has won
            for (GameListener listener : listeners) {
                listener.onPlayerWon(player);
            }
            return true; // signal to the caller that the game is over
        }

        currentPlayerIndex = (currentPlayerIndex + 1) % players.size(); // pass the turn along
        return false; // game continues
    }
}

