import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        // Configure exactly one ladder and one snake on a 30-cell board
        Map<Integer, Integer> snakes = new HashMap<>();
        snakes.put(24, 5); // landing on 24 sends you down to 5
        Map<Integer, Integer> ladders = new HashMap<>();
        ladders.put(3, 22); // landing on 3 sends you up to 22

        // BoardFactory validates the layout before the board is ever created
        Board board = BoardFactory.createBoard(30, snakes, ladders);

        // A deterministic dice sequence makes this demo’s output fully reproducible
        DiceStrategy dice = new FixedSequenceDiceStrategy(new int[]{3, 2, 2, 6});

        Player alice = new Player("Alice");
        Player bob = new Player("Bob");
        List<Player> players = new ArrayList<>();
        players.add(alice); // Alice goes first
        players.add(bob);   // Bob goes second

        SnakeAndLadderGame game = new SnakeAndLadderGame(board, dice, players);
        game.addListener(new ConsoleGameListener()); // print every event as it happens

        // Play exactly 4 turns: Alice, Bob, Alice, Bob
        for (int i = 0; i < 4; i++) {
            game.playTurn();
        }

        // Show where each player ended up after those 4 turns
        System.out.println("Alice final position: " + alice.getPosition());
        System.out.println("Bob final position: " + bob.getPosition());
    }
}

