#include <stdexcept>
using namespace std;

// Strategy pattern: the game does not care HOW a dice value is produced
class DiceStrategy {
public:
    virtual int roll() = 0;
    virtual ~DiceStrategy() {}
};

// Deterministic strategy: replays a fixed list of rolls, then repeats
class FixedSequenceDiceStrategy : public DiceStrategy {
private:
    vector<int> sequence; // the pre-determined rolls to play back
    int index;            // how many rolls have been produced so far

public:
    FixedSequenceDiceStrategy(vector<int> sequence) : sequence(sequence), index(0) {}

    int roll() override {
        int value = sequence[index % sequence.size()]; // wrap around if needed
        index++; // move to the next roll for next time
        return value; // hand back this roll's result
    }
};

// Holds the board size and every snake/ladder mapping in one place
class Board {
private:
    int size;                                  // total number of cells
    unordered_map<int, int> snakesAndLadders;   // start cell maps to destination cell

public:
    Board(int size, unordered_map<int, int> snakesAndLadders)
        : size(size), snakesAndLadders(snakesAndLadders) {}

    int getSize() {
        return size;
    }

    int getFinalPosition(int position) {
        auto it = snakesAndLadders.find(position); // look up this cell
        if (it != snakesAndLadders.end()) return it->second; // found: return the destination
        return position; // not found: the player just stays where they landed
    }
};

// Factory pattern: validates the board configuration before it can exist at all
class BoardFactory {
public:
    static Board createBoard(int size, unordered_map<int, int> snakes, unordered_map<int, int> ladders) {
        unordered_map<int, int> combined;

        for (auto& entry : snakes) {
            if (entry.first <= entry.second) {
                throw invalid_argument("Snake must move a player DOWN the board");
            }
            combined[entry.first] = entry.second;
        }

        for (auto& entry : ladders) {
            if (entry.first >= entry.second) {
                throw invalid_argument("Ladder must move a player UP the board");
            }
            if (combined.find(entry.first) != combined.end()) {
                throw invalid_argument("Cell already has a snake or ladder");
            }
            combined[entry.first] = entry.second;
        }

        return Board(size, combined);
    }
};

// Plain data holder: a player's name never changes, position does
class Player {
public:
    string name;
    int position;

    Player(string name) : name(name), position(0) {} // every player starts off the board
};

// Observer pattern: anything reacting to game events implements this
class GameListener {
public:
    virtual void onSnakeBite(Player& player, int from, int to) = 0;
    virtual void onLadderClimb(Player& player, int from, int to) = 0;
    virtual void onPlayerWon(Player& player) = 0;
    virtual ~GameListener() {}
};

// Concrete listener: prints every event as it happens
class ConsoleGameListener : public GameListener {
public:
    void onSnakeBite(Player& player, int from, int to) override {
        cout << player.name << " bitten by a snake: " << from << " -> " << to << endl;
    }

    void onLadderClimb(Player& player, int from, int to) override {
        cout << player.name << " climbed a ladder: " << from << " -> " << to << endl;
    }

    void onPlayerWon(Player& player) override {
        cout << player.name << " wins the game!" << endl;
    }
};

// Orchestrates the whole game
class SnakeAndLadderGame {
private:
    Board board;
    DiceStrategy* dice;
    vector<Player*> players;
    int currentPlayerIndex;
    vector<GameListener*> listeners;

public:
    SnakeAndLadderGame(Board board, DiceStrategy* dice, vector<Player*> players)
        : board(board), dice(dice), players(players), currentPlayerIndex(0) {}

    void addListener(GameListener* listener) {
        listeners.push_back(listener);
    }

    bool playTurn() {
        Player* player = players[currentPlayerIndex];
        int roll = dice->roll();
        int newPosition = player->position + roll;

        if (newPosition > board.getSize()) {
            currentPlayerIndex = (currentPlayerIndex + 1) % players.size();
            return false;
        }

        int finalPosition = board.getFinalPosition(newPosition);

        if (finalPosition < newPosition) {
            for (auto listener : listeners) {
                listener->onSnakeBite(*player, newPosition, finalPosition);
            }
        } else if (finalPosition > newPosition) {
            for (auto listener : listeners) {
                listener->onLadderClimb(*player, newPosition, finalPosition);
            }
        }

        player->position = finalPosition;

        if (finalPosition == board.getSize()) {
            for (auto listener : listeners) {
                listener->onPlayerWon(*player);
            }
            return true;
        }

        currentPlayerIndex = (currentPlayerIndex + 1) % players.size();
        return false;
    }
};

